INSERT INTO email_templates (name, category, subject, body, variables) VALUES
('Password Reset', 'account', 'Reset Your Password', '<p>Hi {{name}},</p><p>We received a request to reset your password. Click the link below to set a new password:</p><p><a href="{{reset_url}}">Reset Password</a></p><p>This link expires in {{expires_in}}.</p><p>If you did not request this, please ignore this email.</p>', '["name", "reset_url", "expires_in"]'),
('Service Provisioned', 'services', 'Your Service is Ready', '<p>Hi {{name}},</p><p>Your service <strong>{{service_name}}</strong> has been successfully provisioned.</p><p>Access your service at: <a href="{{service_url}}">{{service_url}}</a></p><p>Username: <code>{{username}}</code><br/>Password: <code>{{password}}</code></p>', '["name", "service_name", "service_url", "username", "password"]'),
('Service Suspended', 'services', 'Service Suspended — Action Required', '<p>Hi {{name}},</p><p>Your service <strong>{{service_name}}</strong> has been suspended due to an unpaid invoice.</p><p>Please pay invoice <a href="{{payment_url}}">#{{invoice_id}}</a> to restore access.</p>', '["name", "service_name", "invoice_id", "payment_url"]'),
('Service Terminated', 'services', 'Service Terminated', '<p>Hi {{name}},</p><p>Your service <strong>{{service_name}}</strong> was terminated on {{terminated_at}}. All data has been permanently deleted.</p><p>If this was a mistake, please contact support.</p>', '["name", "service_name", "terminated_at"]'),
('Ticket Opened', 'tickets', 'Ticket #{{ticket_id}} Opened', '<p>Hi {{name}},</p><p>Your support ticket <strong>#{{ticket_id}}: {{ticket_subject}}</strong> has been received. Our team will respond shortly.</p><p><a href="{{ticket_url}}">View Ticket</a></p>', '["name", "ticket_id", "ticket_subject", "ticket_url"]'),
('Ticket Reply', 'tickets', 'New Reply on Ticket #{{ticket_id}}', '<p>Hi {{name}},</p><p>There is a new reply on your ticket <strong>#{{ticket_id}}</strong>:</p><blockquote>{{reply_text}}</blockquote><p><a href="{{ticket_url}}">View Ticket</a></p>', '["name", "ticket_id", "reply_text", "ticket_url"]'),
('Ticket Closed', 'tickets', 'Ticket #{{ticket_id}} Closed', '<p>Hi {{name}},</p><p>Your ticket <strong>#{{ticket_id}}</strong> has been closed. If you need further assistance, please open a new ticket.</p><p><a href="{{ticket_url}}">View Ticket</a></p>', '["name", "ticket_id", "ticket_url"]'),
('New Invoice', 'billing', 'New Invoice #{{invoice_id}}', '<p>Hi {{name}},</p><p>A new invoice has been generated.</p><p><strong>Invoice:</strong> #{{invoice_id}}<br/><strong>Amount:</strong> {{amount}} {{currency}}<br/><strong>Due Date:</strong> {{due_date}}</p><p><a href="{{invoice_url}}">View and Pay Invoice</a></p>', '["name", "invoice_id", "amount", "currency", "due_date", "invoice_url"]'),
('Credit Note Issued', 'billing', 'Credit Note Issued', '<p>Hi {{name}},</p><p>A credit note has been issued to your account for invoice #{{invoice_id}}.</p><p><strong>Amount:</strong> {{amount}} {{currency}}</p><p>The credit will be applied to your next invoice automatically.</p>', '["name", "invoice_id", "amount", "currency"]')
